    static long sqrti(long b) {
        long n = 2;
        if (b < 2) {
            return b;
        }
        long n1 = n - 1;
        long n2 = n;
        long n3 = n1;
        long c = 1;
        long d = (n3 + b) / n2;
        long e = (n3 * d + b / (long) Math.pow(d, n1)) / n2;
        while (c != d && c != e) {
            c = d;
            d = e;
            e = (n3 * e + b / (long) Math.pow(e, n1)) / n2;
        }
        if (d < e) {
            return d;
        } else {
            return e;
        }
    }

    static class Rects {
        long area;
        long w;
        long rwStart;
        long rwEnd;
        long rhStart;
        long rhEnd;

        public Rects(long area) {
            long q = sqrti(area);
            this.area = area;
            this.rwStart = 1;
            this.rwEnd = q;
            this.rhStart = 1;
            this.rhEnd = area;
            this.w = q;
        }

        public static Rects withLimits(long area, long rwStart, long rwEnd, long rhStart, long rhEnd) {
            long q = sqrti(area);
            long maxw = Math.min(q, Math.min(area / rhStart, rwEnd));
            long minw = Math.max(area / rhEnd, rwStart);
            Rects r = new Rects(area);
            r.rwStart = minw;
            r.rwEnd = maxw;
            r.rhStart = rhStart;
            r.rhEnd = rhEnd;
            r.w = maxw;
            return r;
        }

        public long[] next() {
            while (this.w >= this.rwStart) {
                long w = this.w;
                this.w -= 1;
                long h = this.area / w;
                if (h < this.rhStart || h > this.rhEnd || h * w != this.area) {
                    continue;
                }
                return new long[]{w, h};
            }
            return null;
        }
    }

    static Optional<Long> solve(long a, long b) {
        if (a < 1 || b < 1) {
            return Optional.empty();
        }
        long area = a + b;
        Rects outerRects = new Rects(area);
        long[] outer;
        while ((outer = outerRects.next()) != null) {
            long ow = outer[0];
            long oh = outer[1];
            long perimeter = (ow + oh) * 2;

            Rects innerA = Rects.withLimits(a, 1, ow, 1, oh);
            Rects innerB = Rects.withLimits(b, 1, ow, 1, oh);

            long[] inner;
            Rects current = innerA;
            boolean found = false;

            while (true) {
                inner = current.next();
                if (inner != null) {
                    long iw = inner[0];
                    long ih = inner[1];
                    if (iw <= ow && ih <= oh) {
                        found = true;
                        break;
                    }
                } else {
                    if (current == innerA) {
                        current = innerB;
                        continue;
                    } else {
                        break;
                    }
                }
            }

            if (found) {
                return Optional.of(perimeter);
            }
        }
        return Optional.empty();
    }

